import React, { useState } from "react";
import { useParams } from "react-router-dom";
import videosData from "../data/videosData";
import Videos from ".."

const VideoPage = () => {
  const { id } = useParams();
  const course = videosData.find((c) => c.id === id);

  const [currentModule, setCurrentModule] = useState(course?.modules[0]);

  if (!course) {
    return (
      <div className="min-h-screen flex items-center justify-center text-xl">
        Curso não encontrado.
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center p-6">
      {/* Título */}
      <h1 className="text-3xl font-semibold text-center mb-8">{course.title}</h1>

      <div className="flex w-full max-w-6xl bg-white rounded-lg shadow-lg overflow-hidden">
        {/* MÓDULOS */}
        <div className="w-1/4 bg-red-600 text-white p-6">
          <h2 className="text-xl font-semibold mb-6">MÓDULOS</h2>
          <ul>
            {course.modules.map((mod, index) => (
              <li
                key={index}
                className={`flex items-center mb-4 cursor-pointer ${
                  currentModule?.file === mod.file ? "font-bold" : ""
                }`}
                onClick={() => setCurrentModule(mod)}
              >
                <span className="mr-2">✔️</span>
                <span>{mod.title}</span>
              </li>
            ))}
          </ul>
          <button className="mt-6 w-full bg-white text-red-600 font-semibold py-2 px-4 rounded-lg shadow hover:bg-gray-100 transition">
            Material de Apoio
          </button>
        </div>

        {/* PLAYER */}
        <div className="w-3/4 p-6 flex flex-col">
          <div className="relative mb-6">
            <video
              key={currentModule?.file}
              className="w-full h-96 rounded-lg shadow"
              controls
            >
              <source src={currentModule?.file} type="video/mp4" />
              Seu navegador não suporta vídeo.
            </video>
          </div>

          <div className="p-4 bg-gray-100 rounded-lg">
            <p className="text-lg font-medium">{currentModule?.title}</p>
            <p className="text-sm text-gray-500">Duração: --</p>
          </div>
        </div>
      </div>

      {/* MATERIAL DE APOIO */}
      <div className="mt-8 p-4 bg-red-600 text-white text-center w-full max-w-6xl rounded-lg">
        <p>Material de Apoio</p>
      </div>
    </div>
  );
};

export default VideoPage;
